1	// Sample JavaScript AI classifier for testing the Framework-RAI scanner
2	
3	// Import TensorFlow.js
4	import * as tf from '@tensorflow/tfjs';
5	import * as tfvis from '@tensorflow/tfjs-vis';
6	
7	// Define model parameters
8	const NUM_EPOCHS = 20;
9	const BATCH_SIZE = 32;
10	const LEARNING_RATE = 0.01;
11	
12	// Create a simple classifier model
13	function createModel() {
14	  const model = tf.sequential();
15	  
16	  // Add layers
17	  model.add(tf.layers.dense({
18	    inputShape: [10],
19	    units: 32,
20	    activation: 'relu'
21	  }));
22	  
23	  model.add(tf.layers.dropout({ rate: 0.2 }));
24	  
25	  model.add(tf.layers.dense({
26	    units: 16,
27	    activation: 'relu'
28	  }));
29	  
30	  model.add(tf.layers.dense({
31	    units: 3,
32	    activation: 'softmax'
33	  }));
34	  
35	  // Compile model
36	  model.compile({
37	    optimizer: tf.train.adam(LEARNING_RATE),
38	    loss: 'categoricalCrossentropy',
39	    metrics: ['accuracy']
40	  });
41	  
42	  return model;
43	}
44	
45	// Preprocess data
46	async function preprocessData(dataUrl) {
47	  // Fetch data
48	  const response = await fetch(dataUrl);
49	  const data = await response.json();
50	  
51	  // Normalize features
52	  const features = tf.tensor2d(data.features).div(tf.scalar(255.0));
53	  
54	  // One-hot encode labels
55	  const labels = tf.tensor1d(data.labels, 'int32');
56	  const oneHotLabels = tf.oneHot(labels, 3);
57	  
58	  return {
59	    features,
60	    labels: oneHotLabels
61	  };
62	}
63	
64	// Train model
65	async function trainModel(model, data) {
66	  const { features, labels } = data;
67	  
68	  // Define callback for visualization
69	  const callbacks = {
70	    onEpochEnd: (epoch, logs) => {
71	      console.log(`Epoch ${epoch}: loss = ${logs.loss}, accuracy = ${logs.acc}`);
72	      
73	      // Update training visualization (if using tfvis)
74	      tfvis.show.history({ name: 'Training Performance' }, 
75	                         { values: [{ epoch, loss: logs.loss, accuracy: logs.acc }] }, 
76	                         ['loss', 'accuracy']);
77	    }
78	  };
79	  
80	  // Start training
81	  return await model.fit(features, labels, {
82	    epochs: NUM_EPOCHS,
83	    batchSize: BATCH_SIZE,
84	    shuffle: true,
85	    callbacks: callbacks
86	  });
87	}
88	
89	// Evaluate model
90	async function evaluateModel(model, testData) {
91	  const { features, labels } = testData;
92	  
93	  // Get model predictions
94	  const predictions = model.predict(features);
95	  
96	  // Calculate accuracy
97	  const argMax = predictions.argMax(1);
98	  const labelArgMax = labels.argMax(1);
99	  const equality = argMax.equal(labelArgMax);
100	  const accuracy = equality.mean();
101	  
102	  // Convert to scalar and print
103	  const accuracyValue = await accuracy.data();
104	  console.log(`Model accuracy: ${accuracyValue[0]}`);
105	  
106	  return accuracyValue[0];
107	}
108	
109	// Main function
110	async function main() {
111	  try {
112	    // Load and preprocess data
113	    console.log('Loading training data...');
114	    const trainingData = await preprocessData('data/training_data.json');
115	    
116	    console.log('Loading test data...');
117	    const testData = await preprocessData('data/test_data.json');
118	    
119	    // Create model
120	    console.log('Creating model...');
121	    const model = createModel();
122	    
123	    // Display model summary
124	    model.summary();
125	    
126	    // Train model
127	    console.log('Training model...');
128	    await trainModel(model, trainingData);
129	    
130	    // Evaluate model
131	    console.log('Evaluating model...');
132	    const accuracy = await evaluateModel(model, testData);
133	    
134	    // Save model
135	    await model.save('localstorage://my-classifier-model');
136	    console.log('Model saved to browser local storage.');
137	    
138	    console.log('Training complete!');
139	  } catch (error) {
140	    console.error('Error in training:', error);
141	  }
142	}
143	
144	// Run the main function
145	main();

