} catch (e) {
  console.log('✓ Caught error:', e.message);
}

// Test 4: Invalid metric value
console.log('\nTest 4: Invalid metric value (not a number)');
try {
  const result = parseAndValidateThresholds(['exact_match=foo']);
  console.log('✗ Should have thrown error');
} catch (e) {
  console.log('✓ Caught error:', e.message);
}

// Test 5: Out of range (< 0)
