// Simulating CLI validation logic for thresholds
const VALID_METRIC_IDS = ['exact_match', 'toxicity', 'length_variance'];

function parseAndValidateThresholds(thresholdStrings) {
  if (!thresholdStrings || thresholdStrings.length === 0) {
    return {};
  }

  const thresholds = {};

  for (const thresholdStr of thresholdStrings) {
    const parts = thresholdStr.split('=');
    if (parts.length !== 2) {
      throw new Error(`Invalid threshold format: ${thresholdStr}. Must be <metric>=<number>. Valid metrics: ${VALID_METRIC_IDS.join(', ')}`);
    }

    const [metricId, minStr] = parts;
    const min = parseFloat(minStr);

    if (isNaN(min) || min < 0 || min > 1) {
      throw new Error(`Invalid threshold value: ${minStr}. Must be a number between 0 and 1. Valid metrics: ${VALID_METRIC_IDS.join(', ')}`);
    }

    if (!VALID_METRIC_IDS.includes(metricId)) {
      throw new Error(`Unknown metric: ${metricId}. Valid metrics: ${VALID_METRIC_IDS.join(', ')}`);
    }

    thresholds[metricId] = min;
  }

  return thresholds;
}

console.log('=== CLI Validation Tests ===\n');

